mapper.select:
SELECT t1.lms_user_id, t2.user_id, t2.user_name, t4.company_name, t6.course_id, t6.course_name, t8.place_name FROM m_lms_user t1 INNER JOIN m_user t2 ON t1.user_id = t2.user_id LEFT JOIN t_user_company t3 ON t1.lms_user_id = t3.lms_user_id LEFT JOIN m_company t4 ON t3.company_id = t4.company_id LEFT JOIN t_course_user t5 ON t1.lms_user_id = t5.lms_user_id LEFT JOIN m_course t6 ON t5.course_id = t6.course_id LEFT JOIN t_user_place t7 ON t1.lms_user_id = t7.lms_user_id LEFT JOIN m_place t8 ON t7.place_id = t8.place_id
WHERE t1.delete_flg = #{deleteFlg} AND t1.role = '0001'
AND t6.course_id = #{courseId}
AND t4.company_id = #{companyId}
AND t2.user_name LIKE CONCAT('%', #{userName}, '%')
AND t8.place_id = #{placeId}
